import { React, useState, useEffect, Fragment, useCallback } from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"
import ShowSpinner from "./components/ShowSpinner"

const CancelLeave = props => {
  const { currentRacf, setDisplayAlert, superUserMode, convert2MMDDYY, convertToLocal } = props 
  
  const [pendingList, setPendingList] = useState([])

  const [checkedState, setCheckedState] = useState([])

  const refreshCancelLeave = useCallback(() => {

    trackPromise(
      axios({
        url: "eleave/api/ListApprovedByYear",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"
        },

        data: JSON.stringify({ racf: currentRacf, superUser:superUserMode, localTime: convertToLocal(Date.now())})
      })
        .then(response => response.data)
        .then(response => {                    
          const new_pendingList = response["result"]         
          //console.log('cancel', new_pendingList) 
          setPendingList(new_pendingList)
          const new_checkState = new Array(new_pendingList.length).fill(false)
          setCheckedState(new_checkState)
        })
        .catch(error => {
          setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 3000, color: "alert__red" })
          //console.log(error)          
        }),

      "cancelLeave"
    )
    return () => {
      setPendingList(null) // This worked for me
      setCheckedState(null)
    }
    

  }, [currentRacf, setDisplayAlert, superUserMode, convertToLocal])


  useEffect(() => {
    refreshCancelLeave()
  }, [currentRacf, refreshCancelLeave])


  const handleOnChange = position => {
    const updatedCheckedState = checkedState.map((item, index) => (index === position ? !item : item))
    setCheckedState(updatedCheckedState)
  }


  // Please note that below function code appears in Approval Center and Cancel Leave in a slightly different way   
  function checkSelection(pendingList, maxSelect) {

    let num_selected = 0 
    let first_selected = 0 
    const new_pendingList = [...pendingList]    
    let ref_no = "" 

    for (let i = 0; i < checkedState.length; i += 1) {
      if (checkedState[i] === true) {
        num_selected++
        if (first_selected === 0) {
            first_selected = num_selected // this is to note the first selected application 
            ref_no = new_pendingList[i]["ref_no"] 
        }     
        if (num_selected > maxSelect) {
          setDisplayAlert({ message: "select one application at a time please !", position: 3, timeout: 4000, color: "alert__red" } )     
          handleClearAll()           
          return null
        }
      }
    }  
    
    // check if any has been selected
    if (first_selected === 0) {
      setDisplayAlert({ message: "No application has been selected !", position: 3, timeout: 4000, color: "alert__red" } )    
      return null        
    }

    return { ref_no : ref_no, pendingList : pendingList}

  }



  const handleCancel = async () => {

    let new_pendingList = [...pendingList]     
    
    // max selection is virtually no limit so in this case so pass 9999 
    const checkSelectionResult = checkSelection(pendingList, 9999 )

    if ( checkSelectionResult=== null) {
        return null
    }
    
    if (!window.confirm('Are you sure you want to cancel?')) {         
      return null     
    }

    for (let i = 0; i < checkedState.length; i += 1) {
        if (checkedState[i] === true) {
          let options = {
            headers: {
              "Content-type": "application/json",
              api: "yes"
            }
        }

        let data = { refNo: new_pendingList[i]["ref_no"], racf: new_pendingList[i]["racf"], action: "CANCEL", superUser: superUserMode, localTime: convertToLocal(Date.now()) }

        try {
          await trackPromise(axios.post("/eleave/api/changestatus", data, options), "changeStatus")
            .then(response => response.data)
            .then(response => {
              // refNo, racf, action - APPROVE, CANCEL,REJECT, false
              new_pendingList[i]["approvalStatus"] = "CANCEL"                  
            })
            .catch(error => {   
              setDisplayAlert({ message: new_pendingList[i]["ref_no"] + " : " + error.response.data.error_message, position: 4, timeout: 3000, color: "alert__red" })                                          
            })
        } catch (error) {
          setDisplayAlert({ message: error.response.data.error_message, position: 0, timeout: 3000, color: "alert__red" })

        }
      }
    }
    setPendingList(new_pendingList) 
    handleClearAll()    
    refreshCancelLeave()
    return () => {
      setCheckedState(null)
      setPendingList(null)
    }
  }

  const handleSelectAll = () => {
    let allApprovalCheckboxes = document.getElementsByName("cancel")
    for (var i = 0; i < allApprovalCheckboxes.length; i++) {
      allApprovalCheckboxes[i].checked = true
      checkedState[i] = true
    }
  }

  const handleClearAll = () => {
    let allApprovalCheckboxes = document.getElementsByName("cancel")
    for (var i = 0; i < allApprovalCheckboxes.length; i++) {
      allApprovalCheckboxes[i].checked = false
      checkedState[i] = false
    }
  }

   
  const handlePrintReference = async () => {

    let new_pendingList = null 
    let ref_no  = null 
    // max selection is 1 in this case so pass 1 
    const checkSelectionResult = checkSelection(pendingList, 1 )

    if ( checkSelectionResult=== null) {
        return null
    }
    else
    {
      new_pendingList = checkSelectionResult['new_pendingList']
      ref_no = checkSelectionResult['ref_no']
    }

    try {
            // "12/2/22 by VC" - Below is a sample for Billy Chan to build a report   
            const file_name = "Leave Record for " + ref_no + " (" + currentRacf + ").xlsx"            
            //alert("Printing of "+ file_name + " will be coming soon....")
                        
             const response = await trackPromise(
               fetch("/eleave/api/printapply", {
                 method: "POST",
                 headers: {
                   "Content-Type": "application/octet-stream",
                   "Content-Disposition": "attachment",
                   "Cache-Control": "no-cache",
                   "localTime": JSON.stringify(convertToLocal(Date.now())),
                   "parameters": JSON.stringify({ racf: currentRacf,  ref: ref_no})          
                 }
    
             }), "printApply")    
    
             if (!response.ok) {
               const data = await response.text();   
               const msg = JSON.parse(data).error_message          
               setDisplayAlert({ message: msg, position: 3, timeout: 4000, color: "alert__red" } )           
               }
             else {
               const data = await response.blob();          
               //Create blob link to download
               const url = window.URL.createObjectURL(data)
               const link = document.createElement("a")
               link.href = url  
            //   // Give a name of the file 
               link.setAttribute("download", file_name)
               document.body.appendChild(link)
               link.click()
               link.parentNode.removeChild(link)           
             }
            // make sure we return something back from the API     
            return null
    
    }
    catch {               
          setDisplayAlert({ message: "The summary seems no data !  Please check !", position: 3, timeout: 4000, color: "alert__red" })                
    }
    setPendingList(new_pendingList) 
    handleClearAll()        
    return () => {
      setCheckedState(null)
      setPendingList(null)    
     }
  } 

  return (
    <Fragment>
      <div>
        <div>
          <div className="subHeading">Cancel</div>
            
            <table id="cancelLeave_Table"> 

                <tr className="cancelLeave_grid">
                  <th>Select</th>          
                  <th>Ref No.</th>              
                  <th>Applicant</th>
                  <th>Type</th>
                  <th>Status</th>              
                  <th>&nbsp;</th>
                </tr> 

                <tbody>
              
                {pendingList.map((x, index) => (                    
                      <tr key={index} className="cancelLeave_grid">               
                          <td className="cancelLeave_input">
                            <input type="checkbox" name="cancel" value={x.ref} onChange={() => handleOnChange(index)} />
                          </td>
                          <td>{x.ref_no}</td>
                          <td>{x.staff}</td>
                          <td>{x.type}</td>
                          <td>{x.approvalStatus}</td>
                          <td>                     
                                <tr className="cancelLeaveInner_grid">                                         
                                      <th>Start</th>              
                                      <th>End</th>
                                      <th>Working Days</th>
                                </tr>                               
                                
                                {x.details.map((y, index2) => (
                                  <tr key={index2} className="cancelLeaveInner2_grid">
                                    <td>
                                      {convert2MMDDYY(y.startDate)}&nbsp;({y.startTime})
                                    </td>
                                    <td>
                                      {convert2MMDDYY(y.endDate)}&nbsp;({y.endTime})
                                    </td>
                                    <td>{y.workday}</td>
                                  </tr>
                                ))}                      
                          </td>    
                        </tr>                  
                  ))}
             </tbody>

          </table>   

          <ShowSpinner position={4} />


            <div className="cancelLeave">
              <button
                className="fa fa-dot-circle-o"
                onClick={() => {
                  handleSelectAll()
                }}
              >
                &nbsp;Select All
              </button>
              <button
                className="fa fa-circle-o"
                onClick={() => {
                  handleClearAll()
                }}
              >
                &nbsp;Clear All
              </button>
              <button
                className="fa fa-check"
                onClick={() => {
                  handleCancel()
                }}
              >
                &nbsp;Cancel
              </button>

              {<button
                className="fa fa-book"
                onClick={() => {
                  handlePrintReference()
                }}
              >
                &nbsp;Print Reference
              </button>}
            </div>
          </div>
        </div>


    </Fragment>
  )
}

export default CancelLeave
