import React, { useState, Fragment, useEffect } from "react"
import ShowAlert from "./components/ShowAlert"
import SelectType from "./components/SelectType"
import EnterLeave from "./components/EnterLeave"

import { trackPromise } from "react-promise-tracker"
import ShowSpinner from "./components/ShowSpinner"

// for SharePoint
import SharePoint from "./components/sharePoint/SharePoint"
import ShowSharePointFiles from "./components/sharePoint/ShowSharePointFiles"
import UploadForm from "./components/sharePoint/UploadForm"
//import axios from "axios"
import { v4 as uuidv4 } from "uuid"

const ApplyLeave = props => {
  const { currentRacf, superUserMode, setDisplayAlert, userProfile, staff, years, convert2MMDDYY, sharePointPath, convertToLocalTime, alert} = props     
  const [year, setYear] = useState("")
  const [leaveType, setLeaveType] = useState("")  
  const [refreshPage, setRefreshPage] = useState(false)
  const [leaveList, setLeaveList] = useState([])

  // for SharePoints   
  const [sharePointID, setSharePointID] = useState("")    
  const [refreshSharePointList, setRefreshSharePointList] = useState(false)
  const [sharePointFiles, setSharePointFiles] = useState([])
 
  useEffect(() => {
    let root = document.querySelector(":root")
    const userAgent = navigator.userAgent.toLowerCase()
    const isTablet = /(ipad|tablet|(android(?!.*mobile))|(windows(?!.*phone)(.*touch))|kindle|playbook|silk|(puffin(?!.*(IP|AP|WP))))/.test(userAgent)

    // Remove padding of scroll width if it is tablet to make columns of ChangeTrack section aligned
    if (isTablet) {
      root.style.setProperty("--changeTrack_scroll_width", "7fr")
    } else {
      root.style.setProperty("--changeTrack_scroll_width", "6.7fr")
    }

    // check Safari browser
    if (userAgent.includes("safari") && userAgent.includes("macintosh")) {
      root.style.setProperty("--changeTrack_scroll_width", "7fr")
    }
    
  }, [])

  useEffect(() => {    
    setSharePointID(uuidv4())        
  }, [refreshPage])
 
  // convert to local time
  function convertToLocal(date) {
    const t = new Date(date).toTimeString()
    const d = new Date(date).toDateString()
    var local = d + " " + t
    var local_end = local.search("GMT+") - 1
    local = local.substring(0, local_end)
    return local
  }

  
  const printSummary = async (file_name) => {
 
     try {
         // "10/10/22 by VC" - Per request, word "Draft" in the file name will be taken away but the code is still there in case it has to restored
        file_name = "Leave Summary for " + year + " (" + currentRacf + ").xlsx"
                    
        const response = await trackPromise(
          fetch("/eleave/api/printsummary", {
            method: "POST",
            headers: {
              "Content-Type": "application/octet-stream",
              "Content-Disposition": "attachment",
              "Cache-Control": "no-cache",
              "localTime": JSON.stringify(convertToLocal(Date.now())),
              "parameters": JSON.stringify({ year: Number(year), racf: currentRacf })          
            }

        }), "printSummary")    

        if (!response.ok) {
          const data = await response.text();   
          const msg = JSON.parse(data).error_message          
          setDisplayAlert({ message: msg, position: 3, timeout: 4000, color: "alert__red" } )           
        }
        else {
          const data = await response.blob();          
          //Create blob link to download
          const url = window.URL.createObjectURL(data)
          const link = document.createElement("a")
          link.href = url  
          // Give a name of the file 
          link.setAttribute("download", file_name)
          document.body.appendChild(link)
          link.click()
          link.parentNode.removeChild(link)           
        }
        // make sure we return something back from the API
        return null

    }
    catch {}               
      setDisplayAlert({ message: "The summary seems no data !  Please check !", position: 3, timeout: 4000, color: "alert__red" })                
    }

  const handlePrintSummary = event => {
    const id = event.target.id

    if (id === "printSummary") {
      printSummary("Leave Summary.xlsx")
    }
  }

  return (
    <Fragment>

      <div className="subHeading"> Apply Leave</div>
      
      <button id="printSummary" onClick={handlePrintSummary}>
        Print Leave Summary
      </button>

      <SelectType userProfile={userProfile} staff={staff} years={years} year={year} setYear={setYear} leaveType={leaveType} setLeaveType={setLeaveType} setDisplayAlert={setDisplayAlert} currentRacf={currentRacf}
             refreshPage={refreshPage}  convert2MMDDYY={convert2MMDDYY} setLeaveList={setLeaveList}
      />

      {alert.position === 1 ? (
        <div className="flex-row">
          <div className="flex-large">
            <ShowAlert alert={alert} />
          </div>
        </div>
      ) : null}


      {alert.position === 4 ? (
                  <div className="flex-row">
                    <div className="flex-large">
                      <ShowAlert alert={alert} />
                    </div>
                  </div>
      ) : null}
      <ShowSpinner position={4} />

      {/* SharePoint Section starts here */}

      {leaveType && leaveType==="LVE04" ? (
            <div>                          
                <div className={"flex-row " + (true? null : "hideSection")}>
                  <div className="flex-large ">
                    <SharePoint currentRacf={currentRacf} year={year}  office = {userProfile.office}  sharePointPath={sharePointPath} sharePointID={sharePointID} 
                     />          
                  </div>
                </div>

                <div className={"flex-row " + (true ? null : "hideSection")}>
                  <div className="flex-large ">
                    <ShowSharePointFiles   currentRacf={currentRacf} convertToLocalTime={convertToLocalTime} setDisplayAlert={setDisplayAlert} 
                    sharePointID={sharePointID} setRefreshSharePointList={setRefreshSharePointList} refreshSharePointList={refreshSharePointList}
                    setSharePointFiles={setSharePointFiles} sharePointFiles={sharePointFiles} year={year}
                    />
                  </div>
                </div>
              

                <div className={"flex-row " + (true ? null : "hideSection")}>
                  {/* <div className={"flex-row  hideSection"}> */}
                  <div className="flex-large ">
                    <UploadForm setDisplayAlert={setDisplayAlert}  sharePointPath={sharePointPath} currentRacf={currentRacf} sharePointID={sharePointID} userProfile={userProfile} 
                    setRefreshSharePointList={setRefreshSharePointList} year={year} />                                            
                  </div>
                </div>
                </div>
            ):null
    }    

      
    {/* SharePoint Section ends here */}

    <ShowSpinner position={3} />
      <EnterLeave year={year} racf={currentRacf} superUserMode={superUserMode} leaveType={leaveType} setDisplayAlert={setDisplayAlert} setRefreshPage={setRefreshPage} 
      sharePointID={sharePointID}  sharePointFiles={sharePointFiles}   leaveList={leaveList} setLeaveList={setLeaveList}/>


    </Fragment>
  )
}
export default ApplyLeave
