import { React, useState, useEffect, Fragment } from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"
import ShowSpinner from "./ShowSpinner"

const SelectType = props => {
 
  const {setDisplayAlert} = props   

  const {userProfile, leaveType, setLeaveType, year, setYear, currentRacf, refreshPage, convert2MMDDYY,setLeaveList } = props   
  const [balance, setBalance] = useState("")
  const [currentEntitlement, setCurrentEntitlement] = useState("")
  const [yearAry, setYearAry] = useState([])  
  
  useEffect(() => {       
      
      // Find current year 
      if (userProfile.years) {      
        const year_tup = JSON.parse(userProfile.years)      
        const year_ary = year_tup['year']    
        const num_of_years = Object.keys(year_ary).length
        const year_max = Object.values(year_ary)[num_of_years-1]        
  
        if (!(year)) {setYear(year_max)}   // set default to current year 
        if (!(leaveType)) {setLeaveType('LVE01')}   // set default to elave type 
                
        const year_only_ary = []
        for (let i = 0; i < num_of_years; i++) {
          year_only_ary.push( { "year": Object.values(year_ary)[i], "desc" : year_tup['period'][i]  })
        }
        //console.log(year_only_ary)
        setYearAry(year_only_ary)    
      }
  }, [userProfile.years, leaveType, year, setLeaveType, setYear])


  useEffect(() => {           
    if ( !year || !leaveType) {
       return 
    }
     
    // look for the entitlement based on year and leave type    
    const yearEntitlement = userProfile.entitlement.filter(x=>x.year ===Number(year))    //Annual Leave
    
    if (yearEntitlement.length === 0) {            
      return        
    }
   
    if (leaveType  === 'LVE01')  {         
      const lastYearEntitlement = (Number(year) - 1).toString()        
      const annualCarryForward = (yearEntitlement[0].carry_forward).toString()
      const thisYearEntitlement = (yearEntitlement[0].annual_entitlement).toString()
      //console.log('currentEntitlement :',  annualCarryForward + " (" + lastYearEntitlement + ")  +  ("  + thisYearEntitlement   + ") " + year ) 
      const _currentEntitlement = annualCarryForward + " (" + lastYearEntitlement + ")  +  "  + thisYearEntitlement   + " (" + year +")"
      setCurrentEntitlement(_currentEntitlement)  
    }
    else if  (leaveType  === 'LVE02')  {      
      const casualEntitlement = (yearEntitlement[0].casual_entitlement).toString()      
      const _currentEntitlement =  "(" + casualEntitlement   + ") " + year     
      //console.log('currententitlement',_currentEntitlement)
      setCurrentEntitlement(_currentEntitlement)  
    }

    trackPromise(
      axios({
        url: "/eleave/api/listleave",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"         
        },        
        data: JSON.stringify({"year": Number(year), "racf":   currentRacf} )      
      }
    )
    .then(response => response.data)
    .then(response => {          
      const balance_selected = (response['result'][0]["header"]).filter(x=> (x["leaveTypeId"] === leaveType))                             
      setBalance(balance_selected[0])                   
    })
    .catch(error => {
      console.log(error)
    }),
  "typeOfLeave"
    )
    return () => {
      setBalance({}) // This worked for me            
    }


  }, [year, leaveType,  userProfile, setCurrentEntitlement, setDisplayAlert, currentRacf, refreshPage])

  //  Handle select year 
  const handleSelectYear =  event => {    
        const { value } = event.target       
    
            // look for the entitlement based on year and leave type    
        const yearEntitlement = userProfile.entitlement.filter(x=>x.year ===Number(value))    //Annual Leave
        
        if (yearEntitlement.length === 0) {      
          setDisplayAlert({ message: "Year " + String(value) +  " is not available !", position: 1, timeout: 3000, color: "alert__red" })      
          
        }
        setYear(value)          

  }  
      
  //  Handle select type 
  const handleSelectLeaveType = event => {
        const { value } = event.target                
        setLeaveList([])
        setLeaveType(value)           
        
  }    


  const login = () => {
    //localStorage.clear()
    window.location = "/login"
  }

  //  Prevent from loading error due to page refresh
  try {
    if (userProfile.staff.name)  {
      
    }
  }         
  catch
  {
    login()
  }

     
  return (
    <Fragment>
        
      <div>

        <div>        
        
            <div className="separator">Applicant Details</div>        
        
            <div className="emp_grid">            
                <div className="emp_area_a emp_grid_a">
                  <div>Name: </div>              
                  <div>{userProfile.staff.name}</div>              
                </div>

                <div className="emp_area_b emp_grid_b">
                  <div>Position:</div>
                  <div>{userProfile.staff.position}</div>                            
                </div>

                <div className="emp_area_c emp_grid_c">
                  <div>Division/Department: </div>              
                  <div>{userProfile.staff.dept}</div>              
                </div>

                <div className="emp_area_d emp_grid_d">
                  <div>Date Joined:</div>
                  <div>{convert2MMDDYY(userProfile.staff.date_join)}</div>                            
                </div>                           
            </div>            

            <div className="separator">Select Leave Type</div>            
            <div className="type_grid">            
                <div className="type_area_a type_grid_a">
                  <div>Select Leave Type:</div>
                  <div>
                      <select style={{width: '30rem'}} onChange={handleSelectLeaveType} id="selectLeaveTypeOption" className="clickable" value={leaveType}>                                      
                      <option value="LVE01" >
                        Annual Leave
                      </option>
                      {userProfile.staff.office === "DEL" || userProfile.staff.office === "FLR" ? ( 
                          <option value="LVE02" >
                          Casual/ Festivities Leave
                          </option>
                      ) : null}
                      
                      <option value="LVE03" >
                        Work From Home
                      </option>
                      <option value="LVE04" >
                        Sick Leave - With Medical Certificate 
                      </option>
                      <option value="LVE05" >
                        Sick Leave - No Medical Certificate 
                      </option>             
                      </select>
                    </div>
                </div>
                
                <div className="type_area_b type_grid_b" style={{ borderBottom: "2px solid gray", marginLeft: 0, marginRight: 0 }}  >    
                      <div>{(leaveType  === 'LVE01') && "Annual Leave Summary"}
                      {(leaveType  === 'LVE02') && "Casual/ Festivities Leave Summary"}
                      {(leaveType  === 'LVE03') && "Work From Home Summary"}
                      {(leaveType  === 'LVE04') && "Sick Leave - With Medical Certificate Summary"}
                      {(leaveType  === 'LVE05') && "Sick Leave - No Medical Certificate Summary"}
                      </div>                                
                </div>        
                
                <div className="type_area_c type_grid_c"  >
                  <div>Leave Calendar Year:</div>
                  <div>
                      <select style={{width: '30rem'}} onChange={handleSelectYear} id="selectYearOption" className="clickable" 
                      value={
                        year 
                      } >                
                      {/* <option value="Select">Select</option> */}
                      {yearAry.map((x, index) => (
                        <option key={index} value={x.year}>
                         {x.desc}
                      </option>
                      ))}      
                      </select>
                    </div>
                </div>


                <div className="type_area_f type_grid_f">
                      <div>No. of Days Entitled For The Period: </div>   
                      <div>{(leaveType  === 'LVE01' || leaveType  === 'LVE02' )? currentEntitlement: "N/A"}</div>                                           
                </div>

               
                <div className="type_area_d type_grid_d">
                      <div>No. of Days Already Taken (Approved + Pending): </div>                                    
                      <div>{isNaN(balance.taken + balance.pending)?"N/A": (balance.taken + balance.pending) + " (" + balance.taken + " + " + balance.pending + ")"}</div>      
                </div>

                <div className="type_area_e type_grid_e">
                      <div>No. of Days Left: </div>    
                      <div>{(leaveType  === 'LVE01' || leaveType  === 'LVE02' )? balance.balance: "N/A"}</div>              
                </div>

            </div>    
        </div>

      </div>
      <ShowSpinner position={10} /> 
    </Fragment>
  )
  }

export default SelectType